div.script:
document.addEventListener('DOMContentLoaded', function() {
const admissionSelect = document.getElementById('admission_register');
console.log('admissionSelect',admissionSelect)
const courseSelect = document.getElementById('courses');

admissionSelect.addEventListener('change', function() {
const admissionId = this.value;


courseSelect.innerHTML = '<option value="">Select Course';

if (admissionId) {
fetch('/get_courses_by_admission/' + admissionId, {
method: 'GET',
headers: {
'Content-Type': 'application/json'
},
credentials: 'same-origin' // required if user authentication is needed
})
.then(response => response.json())
.then(data => {
data.forEach(course => {
const option = document.createElement('option');
option.value = course.id;
option.textContent = course.name;
courseSelect.appendChild(option);
});
})
.catch(error => console.error('Error fetching courses:', error));
}
});
});
